      .stroke({ color: '#e68600', width: 5, linecap: 'round', opacity: 0.8 });
  }
}

function drawTree(group, a, frame) {
  for (var e = 0; e < edges.length; e++) {
    if (edges[e][0] <= a.length && edges[e][1] <= a.length) {
      var p1 = pos[edges[e][0]], p2 = pos[edges[e][1]];
      group.line(p1[0], p1[1], p2[0], p2[1]).stroke({ color: '#111', width: 1.6 });
    }
  }
  drawOperationHighlight(group, frame);

  for (var i = 1; i <= a.length; i++) {
    if (!pos[i]) continue;
    var p = pos[i];
    var fill = '#e6e6e6';
    if (frame.wrongIndices && frame.wrongIndices.indexOf(i) >= 0) fill = '#ffc4c4';
    if (frame.kind === 'swap' && frame.indices.indexOf(i) >= 0) fill = '#ffd59e';
    if ((frame.kind === 'greater' || frame.kind === 'compare') && frame.indices.indexOf(i) >= 0) fill = '#dcecff';
    if (nodeIsCurrent(frame, i)) fill = '#9c9c9c';

    var c = group.circle(54).center(p[0], p[1]).fill(fill).stroke({ color: '#111', width: 1.2 });
    (function(idx) {
      c.on('mousemove', function(e) { showTooltip('Node index ' + idx + ', value ' + a[idx-1], e); })
       .on('mouseleave', function() { hideTooltip(); })
       .on('click', function() { showPopup('Heap node ' + idx, 'In a 1-based array heap, this node’s left child is at ' + (2*idx) + ' and right child is at ' + (2*idx+1) + '.'); })
       .css('cursor', 'pointer');
    })(i);

    group.text(String(a[i-1])).font({ family: 'serif', size: 25 }).center(p[0], p[1] + 1);
    var labelPos = indexLabelPosition(i);
    textHalo(group.text(String(i)).font({ family: 'serif', size: 17 }).center(labelPos[0], labelPos[1]).fill('#000'));

    if (nodeIsCurrent(frame, i)) {
      textHalo(group.text('i').font({ family: 'serif', size: 23, style: 'italic' }).center(p[0] - 45, p[1] - 5).fill('#000'));
    } else if (frame.marks && frame.marks[i] && frame.marks[i] !== 'current') {
      textHalo(group.text(frame.marks[i]).font({ family: 'sans-serif', size: 12 }).center(p[0] + 50, p[1] - 17).fill('#333'));
    }
  }
}

function indexLabelPosition(i) {
  var p = pos[i];
  var offsets = {
    1: [0,-42], 2: [-38,-31], 3: [38,-31], 4: [-38,-31], 5: [0,-42],
    6: [-38,-31], 7: [38,-31], 8: [-32,-33], 9: [0,-42], 10: [0,-42]
  };
  var o = offsets[i] || [0,-40];
  return [p[0] + o[0], p[1] + o[1]];
}

function drawFrame(idx) {
  if (!frames.length) frames = [initialFrame()];
  if (idx < 0) idx = 0;
  if (idx >= frames.length) idx = frames.length - 1;
  frameIndex = idx;
  var frame = frames[frameIndex];
  g.clear();
  ensureArrowMarker();

  drawArray(g, frame.state, frame);
  drawTree(g, frame.state, frame);

  var opText = frame.kind === 'ready' ? 'MAX-HEAPIFY has not run yet' :
               frame.kind === 'final' ? 'BUILD-MAX-HEAP complete' :
               frame.kind === 'error' ? 'Error while running code' :
               ('MAX-HEAPIFY(A, ' + (frame.callI || '?') + ')');
  textHalo(g.text(opText).font({ family: 'sans-serif', size: 19 }).move(42, 91).fill('#222'));

  drawCallOrder(g, frame);

  document.getElementById('frameCounter').textContent = (frameIndex + 1) + ' of ' + frames.length;
  document.getElementById('frameCaption').textContent = frame.message || '';
  document.getElementById('heapifyLog').value = frames.map(function(f, k) {
    return (k + 1) + '. ' + (f.message || f.kind);
  }).join('\n');
}

function setStatus(text) {
