function trigger_runBuild() {
  stopPlay();
  requestedFinalDemo = false;
  var input;
  try { input = parseArrayText(document.getElementById('heapifyCodeInput').value); }
  catch (e) {
    frames = [Object.assign(initialFrame(), { kind: 'error', message: e.message, status: 'error' })];
    lastRunStatus = 'error';
    setStatus('error');
    drawFrame(0);
    return;
  }

  if (currentWorker) currentWorker.terminate();
  setStatus('running');
  lastRunStatus = 'running';
  document.getElementById('runBuildInput').disabled = true;

  var blob = new Blob([workerSource()], { type: 'application/javascript' });
  var url = URL.createObjectURL(blob);
  var worker = new Worker(url);
  currentWorker = worker;

  var timedOut = false;
  var timer = setTimeout(function() {
    timedOut = true;
    worker.terminate();
    URL.revokeObjectURL(url);
    currentWorker = null;
    frames = [Object.assign(initialFrame(), { kind: 'error', message: 'Error: timeout. Your code may contain an infinite loop that does not call the API.', status: 'error' })];
    lastRunStatus = 'error';
    setStatus('error / timeout');
    document.getElementById('runBuildInput').disabled = false;
    drawFrame(0);
  }, 1800);

  worker.onmessage = function(e) {
    if (timedOut) return;
    clearTimeout(timer);
    URL.revokeObjectURL(url);
    currentWorker = null;
    document.getElementById('runBuildInput').disabled = false;
    frames = e.data.frames || [];
    lastRunStatus = e.data.status || 'error';
    if (lastRunStatus === 'correct') setStatus('correct');
    else if (lastRunStatus === 'wrong') setStatus('wrong answer');
    else setStatus('error');
    drawFrame(requestedFinalDemo ? frames.length - 1 : 0);
  };

  worker.onerror = function(e) {
    if (timedOut) return;
    clearTimeout(timer);
    URL.revokeObjectURL(url);
    currentWorker = null;
    document.getElementById('runBuildInput').disabled = false;
    frames = [Object.assign(initialFrame(), { kind: 'error', message: 'Worker error: ' + (e.message || 'unknown error'), status: 'error' })];
    lastRunStatus = 'error';
    setStatus('error');
    drawFrame(0);
  };

  worker.postMessage({ code: document.getElementById('heapifyCodeCode').value, input: input });
}

function firstFrame() { stopPlay(); drawFrame(0); }
function prevFrame() { stopPlay(); drawFrame(frameIndex - 1); }
function nextFrame() { stopPlay(); drawFrame(frameIndex + 1); }

function stopPlay() {
  if (playTimer) clearInterval(playTimer);
  playTimer = null;
  document.getElementById('playBtn').textContent = '▶';
}

function togglePlay() {
  if (playTimer) { stopPlay(); return; }
  document.getElementById('playBtn').textContent = '❚❚';
  playTimer = setInterval(function() {
    if (frameIndex >= frames.length - 1) { stopPlay(); return; }
    drawFrame(frameIndex + 1);
  }, 700 / Number(document.getElementById('speedInput').value || 1));
}

function applyStep() {
  var s = demoSteps[stepIndex];
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (stepIndex + 1) + ' / ' + demoSteps.length + ': ' + s.title;
  if (s.state.runBuild === 'idle') {
    requestedFinalDemo = false;
    stopPlay();
    frames = [initialFrame()];
    lastRunStatus = 'not-run';
    setStatus('not run');
    drawFrame(0);
  } else if (s.state.runBuild === 'running') {
    if (lastRunStatus === 'not-run' || lastRunStatus === 'error') trigger_runBuild();
  } else if (s.state.runBuild === 'done') {
    stopPlay();
    if (frames.length && (lastRunStatus === 'correct' || lastRunStatus === 'wrong')) {
      drawFrame(frames.length - 1);
    } else if (lastRunStatus === 'running') {
      requestedFinalDemo = true;
    } else {
      frames = [textbookFinalFrame()];
      lastRunStatus = 'correct';
      setStatus('textbook final shown');
      drawFrame(0);
    }
  }
}

function prevStep() {
  stepIndex = Math.max(0, stepIndex - 1);
  applyStep();
}

function nextStep() {
  stepIndex = Math.min(demoSteps.length - 1, stepIndex + 1);
  applyStep();
}

